/* From Uiverse.io by naelawadallah  - Tags: input, dark, search */
.__UIV_SCOPE__ .search-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  text-align: center;
}

.__UIV_SCOPE__ .search-header__input {
  font-family: inherit;
  font-size: 16px;
  background-color: #0a0a0a;
  border: solid 0.5px #525252;
  color: #646464;
  padding: 0.7rem 1rem;
  border-radius: 25px;
  width: 240px;
  height: 48px;
  transition: all ease-in-out 0.5s;
  margin-right: -2rem;
  opacity: 1;
  text-align: center;
}

.__UIV_SCOPE__ .search-header__input:hover,
.__UIV_SCOPE__ .search-header__input:focus {
  box-shadow: 0 0 1em #00000013;
}

.__UIV_SCOPE__ .search-header__input:focus {
  outline: none;
  background-color: #0a0a0aad;
}

.__UIV_SCOPE__ .search-header__input::-webkit-input-placeholder {
  font-weight: 100;
  color: #3a3a3a;
}

.__UIV_SCOPE__ .search-header__input:focus + .search-header__button {
  background-color: transparent;
}

.__UIV_SCOPE__ .search-header__button {
  border: none;
  background-color: transparent;
  margin-top: 0.1em;
}

.__UIV_SCOPE__ .search-header__button:hover {
  cursor: pointer;
}

.__UIV_SCOPE__ .search-header__icon {
  height: 1.3em;
  width: 1.3em;
  fill: #3a3a3a;
}
